let partsTab='Stock',assemblyRowCount=0,setupReview=null;
const liveAssemblies=()=>db.assemblies.filter(a=>!a.dismantled);
const componentLabel=p=>p.name+(p.reference?' ['+p.reference+']':p.tracking==='individual'?' ['+p.id.slice(0,8)+']':'');
function stockEditAction(p){const a=liveAssemblies().find(a=>a.components.some(c=>c.partId===p.id));return a?`<p class="tiny muted">Reserved in ${esc(a.name)}. Dismantle the group before editing this stock.</p>${btn('View assemblies','parts-tab','','Assemblies')}`:btn('Edit part','edit-part','',p.id);}
function renderParts(){
  if(!local())return renderStock();
  const tabs=`<div class="tabs"><button data-action="parts-tab" data-id="Stock" class="${partsTab==='Stock'?'active':''}">${icon('box')}Stock</button><button data-action="parts-tab" data-id="Assemblies" class="${partsTab==='Assemblies'?'active':''}">${icon('assembly')}Assemblies (${db._view?.assemblies??liveAssemblies().length})</button></div>`;
  if(partsTab==='Stock')return renderStock(tabs);
  if(partsTab==='Build from Scratch')return renderBuild(tabs);
  return heading('Assemblies','Combine components into a physical unit, ready to install.',btn(icon('plus')+' Build assembly','add-assembly','primary'))+tabs+
    `<div class="note info">Assembly components are reserved from your stock. Install, transfer or remove the whole group, or dismantle it to work with its parts separately.</div>`+
    (liveAssemblies().length?`<div class="two-col mt">${liveAssemblies().map(a=>panel(a.name,
      `<div class="row">${badge(a.carId?'Installed':'In storage',a.carId?'good':'')}<span class="muted">${esc(a.carId?db.cars.find(c=>c.id===a.carId)?.name:a.location)}</span></div>`+
      `<div class="assembly-components">${a.components.map(c=>{const p=db.parts.find(p=>p.id===c.partId);return `<div class="list-row"><div><strong>${esc(componentLabel(p))}</strong><div class="tiny muted">${c.quantity} piece(s) · ${esc(techLabels[c.field]||c.position)} · ${esc(p.condition)}</div></div></div>`;}).join('')}</div>`+
      `<p class="prewrap muted">${esc(a.notes)}</p>${a.history?.length?`<details><summary>Component replacement history (${a.history.length})</summary>${a.history.slice().reverse().map(e=>`<p class="tiny">${date(e.date)} · ${esc(e.removedName)} → ${esc(e.installedName)}</p>`).join('')}</details>`:''}<div class="actions">${btn(a.carId?'Transfer…':'Install on car…','install-assembly','primary small',a.id)}${a.carId?btn('Remove to storage…','remove-assembly','small',a.id):''}${btn('Replace component…','replace-assembly','small',a.id)}${btn('Dismantle…','dismantle-assembly','small',a.id)}</div>`)).join('')}</div>`:
      empty('Build your first assembly','Choose components from available stock. They will remain linked as one physical group.',btn('Build assembly','add-assembly','primary')))+viewPager(db._view?.list);
}
function assemblyRow(){
  const n=assemblyRowCount++;
  return `<div class="assembly-row panel"><h3>Component ${n+1}</h3><div class="form-grid"><label class="field">Stock<select name="component${n}"><option value="">Choose a part</option>${db.parts.filter(p=>available(p)>0).map(p=>`<option value="${p.id}">${esc(componentLabel(p))} · ${esc(p.condition)} · ${available(p)} free</option>`).join('')}</select></label>${field('quantity'+n,'Quantity (pieces)',1,'number')}<label class="field">Technical position<select name="field${n}"><option value="">Inventory only</option>${Object.entries(techLabels).filter(([k])=>slotforgeDomain.componentFields.includes(k)).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label>${field('position'+n,'Position / description','')}</div></div>`;
}
function createAssembly(){
  const revision=db.revision;assemblyRowCount=0;
  modal('Build an assembly',`<p class="muted">Selected quantity stock is separated into a dedicated lot. Empty component rows are ignored.</p><div class="form-grid">${field('name','Assembly name','')}${field('location','Storage location','Assembly storage','text',db.parts.map(p=>p.location).filter(Boolean))}${field('notes','Notes','','textarea')}</div><div id="assembly-rows">${assemblyRow()}${assemblyRow()}</div>${btn('Add component row','assembly-row')}`,async values=>{
    const components=[];for(let n=0;n<assemblyRowCount;n++)if(values['component'+n])components.push({partId:values['component'+n],quantity:Number(values['quantity'+n]),field:values['field'+n],position:values['position'+n]});
    await change('assembly.create',{name:values.name,location:values.location,notes:values.notes,components,revision});partsTab='Assemblies';
  },'Build assembly');
}
function installAssemblyDialog(id){
  const a=liveAssemblies().find(a=>a.id===id),revision=db.revision;
  const cars=db.cars.filter(c=>!c.archived&&c.id!==a.carId);
  if(!cars.length){toast('Add another available car first.');return;}
  modal(a.carId?'Transfer assembly':'Install assembly',`<p><strong>${esc(a.name)}</strong> · ${a.components.length} components</p>${a.carId?`<div class="note">This removes the entire group from ${esc(db.cars.find(c=>c.id===a.carId).name)} and records the transfer in both cars’ histories.</div>`:''}<label class="field">Destination car<select name="carId">${cars.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><p class="muted">Existing tracked components in the same positions must be removed first.</p><label class="check-row"><input type="checkbox" name="confirmed" required>I have physically installed this complete assembly on the selected car.</label>`,async values=>change('assembly.install',{id,revision,carId:values.carId,allowTransfer:!!a.carId}),a.carId?'Record transfer':'Record installation');
}
function removeAssemblyDialog(id){const a=liveAssemblies().find(a=>a.id===id),revision=db.revision;modal('Remove assembly',`<p>Return <strong>${esc(a.name)}</strong> to storage as a complete group. Its components will be marked Used and stay reserved.</p>${field('location','Return location','Used spares')}<label class="check-row"><input name="confirmed" type="checkbox" required>I have removed the complete assembly from the car.</label>`,async values=>change('assembly.remove',{id,revision,location:values.location}),'Record removal');}
function dismantleAssemblyDialog(id){const a=liveAssemblies().find(a=>a.id===id),revision=db.revision;modal('Dismantle assembly',`<p>Dismantle <strong>${esc(a.name)}</strong>?</p><div class="note">${a.carId?'Its components stay installed on the car as separate parts. Remove them individually if you also take them off the car.':'Its components become available as separate stock in their existing locations.'} Earlier setup snapshots and installation history are preserved.</div>`,async()=>change('assembly.dismantle',{id,revision}),'Dismantle group');}
async function openApplySetup(id){
  const model=await api('plan','setup.options',{id});setupReview={id,revision:model.revision,model};
  modal('Apply setup · '+model.setup.name,`<div class="note info">Choose the actual components you will use, then review every movement. No changes are saved until the final confirmation. If stock is missing, add it or choose an explicit substitute.</div>${model.rows.length?model.rows.map(r=>`<section class="panel mt"><h3>${esc(r.name)}</h3><p class="tiny muted">${r.kind==='assembly'?r.components.length+' components · complete assembly':r.quantity+' piece(s) · '+esc(techLabels[r.field]||r.position||'Inventory only')}</p><label class="field">Use this ${r.kind==='assembly'?'assembly':'component'}<select name="pick${r.key}"><option value="">Choose stock or an installed component</option>${r.choices.map(c=>`<option value="${esc(c.value)}" ${r.selected===c.value?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label></section>`).join(''):'<p>This snapshot has no tracked inventory. Currently installed parts will be returned to used spares; assemblies will remain together in storage.</p>'}<div class="actions mt">${btn('Review changes →','preview-setup','primary')}</div>`,null);
}
async function previewSetup(){
  const selections={};for(const r of setupReview.model.rows)selections[r.key]=$(`[name="pick${r.key}"]`).value;
  const payload={id:setupReview.id,revision:setupReview.revision,selections};
  let preview;try{preview=await api('plan','setup.preview',payload);}catch(e){$('#form-error').textContent=e.message;$('#form-error').hidden=false;return;}
  modal('Review setup · '+preview.setupName,`<p>Apply to <strong>${esc(preview.carName)}</strong>. This records the configuration you actually build; the saved snapshot remains unchanged.</p>${panel('Inventory movements',preview.changes.length?`<ul class="review-list">${preview.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:'<p class="muted">No tracked inventory movements.</p>')}<div class="table-wrap mt"><table><thead><tr><th>Setting</th><th>Current</th><th>After applying</th></tr></thead><tbody>${preview.fields.map(f=>`<tr><td>${esc(techLabels[f.key]||f.key)}</td><td>${esc(f.before||'—')}</td><td>${esc(f.after||'—')}</td></tr>`).join('')||'<tr><td colspan="3">Technical settings already match.</td></tr>'}</tbody></table></div>${preview.transfers.length?`<div class="note mt"><strong>Transfers from other cars</strong><ul>${preview.transfers.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><label class="check-row"><input name="transfers" type="checkbox" required>I confirm these components are moving from the listed cars.</label></div>`:''}<label class="check-row mt"><input name="confirmed" type="checkbox" required>I have made the listed physical changes and checked the resulting settings.</label><p class="tiny muted">All changes are saved together. If stock changes before saving, reopen Apply setup and review again.</p><div class="actions">${btn('← Change selections','apply-setup','',payload.id)}</div>`,async values=>{await change('setup.apply',{...payload,confirmed:!!values.confirmed,allowTransfers:!!values.transfers});toast('Setup applied. Inventory and history updated.');},'Apply reviewed setup');
}
